#!/usr/bin/env python3
"""Committed float32 golden reference for the functions in ``include/ulpgrad``.

Writes one CSV per function under ``data/reference/``::

    # generated by experiments/m3_fit/gen_golden.py
    # function: exp
    # reference: mpmath 1.4.1 at 40 decimal digits, direct round-to-nearest-even to float32
    # seed: 0x5EED0001
    # points: 8887
    # columns: input_bits_hex,output_bits_hex
    3f800000,402df854
    ...

Both columns are raw IEEE-754 binary32 patterns in hexadecimal, so the C++ side
reads integers and never parses a decimal.

The reference is ``mp.exp(x)`` / ``2**x`` at 40 decimal digits, rounded to
float32 by an explicit round-to-nearest-even on the significand. It is *not*
``float()``: going through binary64 would double round (53 bits, then 24) and
disagree with direct rounding on exact ties. The rounding routine, the LCG, the
bit helpers and the exp border set are imported from
``experiments/m0_exp/gen_reference.py`` -- the code that produced the measured
1 ULP bound -- rather than re-derived here.

The sample is stratified so that the bucket table in ``data/error-bounds.json``
can fail in the ranges where it is cheapest to fail:

  uniform      dense mid-range values, where the reduction is exercised
  wide         the whole finite argument range, so every output exponent appears
  borders      reduction boundaries k*ln2 and (k +- 1/2)*ln2 (exp) or integers
               and half-integers (exp2), each +- 2 ULP
  thresholds   overflow, subnormal onset and underflow, +- 4 ULP
  subnormal    subnormal arguments, both signs
  specials     NaN with payload, +-inf, +-0, largest finite, smallest subnormal

Run from the repository root::

    python experiments/m3_fit/gen_golden.py
"""

import argparse
import math
import os
import sys
import time

import mpmath
import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, os.path.join(REPO, 'experiments', 'm0_exp'))

import gen_reference as gr  # noqa: E402  (path has to be set first)

MP_DPS = 40
F32_INF = 0x7F800000
F32_MAX = 0x7F7FFFFF
F32_MIN_SUB = 0x00000001
F32_QNAN = 0x7FC00000

DEFAULT_SEED = 0x5EED0003


# --------------------------------------------------------------------------- #
# the references
#
# One function per entry. Each takes an exact mpmath value and returns an mpmath
# value; a NaN result means "this argument has no real result" and becomes the
# canonical quiet NaN pattern, which is what the headers promise. The domain
# guards live here rather than in the shared driver so that a reader sees the
# contract of each function next to its reference.
# --------------------------------------------------------------------------- #


def ref_exp(x):
    """exp(x) in mpmath, x an exact float32 value."""
    return mpmath.exp(x)


def ref_exp2(x):
    """2**x in mpmath, x an exact float32 value."""
    return mpmath.power(2, x)


def ref_rsqrt(x):
    """1/sqrt(x): +-inf at +-0, a NaN for a negative argument.

    The argument arrives as a Python float, which is exact for a float32 and --
    unlike `mpmath.mpf` -- keeps the sign of a zero: `rsqrt(-0)` is `-inf`, not
    `+inf`, and a reference that lost that bit would certify the wrong answer.
    """
    if x == 0.0:
        return mpmath.inf if math.copysign(1.0, x) > 0.0 else mpmath.ninf
    if x < 0.0:
        return mpmath.nan
    return 1 / mpmath.sqrt(mpmath.mpf(x))


def ref_tanh(x):
    """tanh(x): +-1 at +-inf, and the sign of a zero preserved."""
    if x == 0.0:
        return x          # mpmath has no signed zero, and tanh(-0) is -0
    return mpmath.tanh(mpmath.mpf(x))


def ref_log(x):
    """ln(x): -inf at +-0, a NaN for a negative argument."""
    if x == 0.0:
        return mpmath.ninf
    if x < 0.0:
        return mpmath.nan
    return mpmath.log(mpmath.mpf(x))


def ref_log2(x):
    """log2(x): the same domain, divided by ln2 at 40 digits, not by a float."""
    if x == 0.0:
        return mpmath.ninf
    if x < 0.0:
        return mpmath.nan
    return mpmath.log(mpmath.mpf(x)) / mpmath.log(2)


def ref_log1p(x):
    """ln(1 + x): -inf at -1, a NaN below it, and the sign of a zero preserved."""
    if x == -1.0:
        return mpmath.ninf
    if x < -1.0:
        return mpmath.nan
    if x == 0.0:
        # mpmath has no signed zero, and `log1p(-0)` is `-0`. Returning the float
        # itself tells the driver to take the pattern verbatim.
        return x
    return mpmath.log1p(mpmath.mpf(x))


# --------------------------------------------------------------------------- #
# samples
# --------------------------------------------------------------------------- #


def uniform_bits(n, seed, lo, hi):
    """n patterns of floats uniform in [lo, hi]; deterministic LCG, no numpy RNG."""
    u = (gr.lcg_u32(n, seed) >> np.uint32(8)).astype(np.float64) / float(1 << 24)
    return (lo + (hi - lo) * u).astype(np.float32).view(np.uint32)


def dedupe(seq):
    """Unique patterns in first-seen order (a repeated point measures twice)."""
    seen = set()
    out = []
    for bits in seq:
        value = int(bits)
        if value not in seen:
            seen.add(value)
            out.append(value)
    return np.array(out, dtype=np.uint32)


def subnormal_bits(n, seed):
    """n subnormal arguments, deterministic, both signs."""
    raw = gr.lcg_u32(n, seed)
    magnitude = (raw % np.uint32(0x7FFFFF)).astype(np.uint32) + np.uint32(1)
    sign = np.where((raw & np.uint32(1)) != 0, np.uint32(0x80000000), np.uint32(0))
    return (magnitude | sign).astype(np.uint32)


def special_bits():
    """NaN payloads, infinities, both zeros, the finite extremes."""
    return np.array([
        0x7FC00001,   # quiet NaN, non-zero payload
        0x7F800001,   # signalling NaN, non-zero payload
        0xFFC00000,   # negative quiet NaN
        0x7F800000,   # +inf
        0xFF800000,   # -inf
        0x00000000,   # +0
        0x80000000,   # -0
        F32_MAX,      # largest finite
        F32_MIN_SUB,  # smallest positive subnormal
        0x80000001,   # smallest negative subnormal
    ], dtype=np.uint32)


def reference_one(xbits, func):
    """Correctly rounded float32 result for one input pattern.

    A NaN argument keeps its own payload; a NaN *result* becomes the canonical
    quiet NaN the headers promise, so the measurement can compare it bit for bit
    instead of inventing a ULP distance for a pattern with no position on the
    real line. Infinities go through the reference function: `exp(-inf)` and
    `rsqrt(+inf)` are perfectly good results, and short-circuiting them here
    would hide a wrong sign.
    """
    bits = int(xbits)
    if gr.is_nan_bits(bits):
        return bits                            # NaN propagates with its payload
    value = func(gr.bits_to_float(bits))
    if mpmath.isnan(value):
        return F32_QNAN
    if isinstance(value, float):
        return gr.float_to_bits(value)         # a signed zero, taken verbatim
    return gr.round_to_f32_bits(value)


def bisect_bits(lo, hi, predicate):
    """Smallest pattern in [lo, hi] where the monotone predicate holds."""
    return gr._bisect_bits(lo, hi, predicate)  # noqa: SLF001  (shared with the m0 spike)


# --------------------------------------------------------------------------- #
# per-function strata
# --------------------------------------------------------------------------- #


def exp_borders():
    """The m0 border set: k*ln2 and (k +- 1/2)*ln2, plus every threshold."""
    return gr.border_sample()


def exp2_overflow_bits():
    """Smallest float32 x whose correctly rounded 2**x is +inf."""
    def rounds_to_inf(bits):
        return reference_one(bits, ref_exp2) == F32_INF

    return bisect_bits(0x42FE0000, 0x43000000, rounds_to_inf)   # 127.0 .. 128.0


def exp2_underflow_bits():
    """Largest float32 x whose correctly rounded 2**x is +0."""
    def rounds_to_zero(bits):
        return reference_one(bits, ref_exp2) == 0

    # For negative x the raw pattern grows as the value falls, so the predicate
    # is monotone in the bits and the first match is the largest such x.
    return bisect_bits(0xC3100000, 0xC3200000, rounds_to_zero)  # -144.0 .. -160.0


def exp2_subnormal_onset_bits():
    """Smallest-magnitude x whose correctly rounded 2**x is subnormal."""
    def is_subnormal(bits):
        value = reference_one(bits, ref_exp2)
        return (value & 0x7F800000) == 0 and (value & 0x007FFFFF) != 0

    return bisect_bits(0xC2F00000, 0xC2FE0000, is_subnormal)    # -120.0 .. -127.0


def exp2_borders():
    """Integer and half-integer reduction boundaries, plus every threshold."""
    out = []
    for k in range(-150, 129, 3):
        for offset in (0.0, 0.5, -0.5):
            out.extend(gr._neighbours(gr.round_to_f32_bits(mpmath.mpf(k + offset)), reach=2))
    out.extend(gr._neighbours(exp2_overflow_bits(), reach=4))
    out.extend(gr._neighbours(exp2_underflow_bits(), reach=4))
    out.extend(gr._neighbours(exp2_subnormal_onset_bits(), reach=4))
    return dedupe(out)


def exp_sample(seed, uniform_dense, uniform_wide, subnormal_points):
    return [
        ('uniform', uniform_bits(uniform_dense, seed, -30.0, 30.0)),
        ('wide', uniform_bits(uniform_wide, seed ^ 0x9E3779B9, -104.0, 88.8)),
        ('borders', exp_borders()),
        ('subnormal', subnormal_bits(subnormal_points, seed ^ 0x51ED270B)),
        ('specials', special_bits()),
    ]


def exp2_sample(seed, uniform_dense, uniform_wide, subnormal_points):
    return [
        ('uniform', uniform_bits(uniform_dense, seed, -20.0, 20.0)),
        ('wide', uniform_bits(uniform_wide, seed ^ 0x9E3779B9, -150.0, 128.0)),
        ('borders', exp2_borders()),
        ('subnormal', subnormal_bits(subnormal_points, seed ^ 0x51ED270B)),
        ('specials', special_bits()),
    ]


def structural_positive_sample():
    """254 normal exponents x 4 mantissa quarters: the shape of the reduction.

    `rsqrt` and `log` both split the exponent, not the value, so a sample that
    only walks magnitudes would miss whole classes of mantissa. Both signs are
    not useful here: a negative argument has no real result and lands in the
    special-case tests.
    """
    exps = np.arange(1, 255, dtype=np.uint32)
    fracs = np.array([0x000000, 0x200000, 0x400000, 0x600000], dtype=np.uint32)
    return ((exps[:, None] << np.uint32(23)) | fracs[None, :]).ravel().astype(np.uint32)


def around(bits, reach):
    """The +-reach float32 neighbours of a pattern, specials excluded."""
    return gr._neighbours(bits, reach=reach)


def rsqrt_borders():
    """Every exponent's mantissa quarters, the parity split and the edges."""
    out = list(structural_positive_sample())
    # The reduction makes the exponent even; M jumps from just under 4 to 1 when
    # the exponent crosses an even boundary, so both sides of that step are here.
    for field in range(1, 255, 7):
        base = np.uint32(field) << np.uint32(23)
        out.extend(around(int(base), 3))
        out.extend(around(int(base | np.uint32(0x007FFFFF)), 3))
    out.extend(around(int(np.float32(1.0).view(np.uint32)), 40))
    out.extend(around(0x00800000, 4))          # smallest normal
    out.extend(around(F32_MIN_SUB, 4))         # smallest subnormal
    out.extend(around(F32_MAX, 4))             # largest finite
    out.extend(around(int(np.float32(4.0).view(np.uint32)), 8))
    return dedupe(out)


def rsqrt_sample(seed, uniform_dense, uniform_wide, subnormal_points):
    return [
        ('uniform', uniform_bits(uniform_dense, seed, 0.01, 100.0)),
        ('wide', uniform_bits(uniform_wide, seed ^ 0x9E3779B9, 1e-30, 1e30)),
        ('borders', rsqrt_borders()),
        ('subnormal', subnormal_bits(subnormal_points, seed ^ 0x51ED270B)),
        ('specials', special_bits()),
    ]


def log_borders():
    """Every exponent's mantissa quarters, the sqrt(2) split, and the edges.

    The reduction halves the mantissa when it exceeds sqrt(2), so the f32 pattern
    of sqrt(2) and of `1.0` are the two places a bit of the split can go wrong.
    """
    out = list(structural_positive_sample())
    out.extend(around(int(np.float32(1.0).view(np.uint32)), 200))
    root2 = int(np.float32(math.sqrt(2.0)).view(np.uint32))
    out.extend(around(root2, 8))
    half_root2 = int(np.float32(0.5 * math.sqrt(2.0)).view(np.uint32))
    out.extend(around(half_root2, 8))
    out.extend(around(0x00800000, 4))          # smallest normal
    out.extend(around(F32_MIN_SUB, 4))         # smallest subnormal
    out.extend(around(F32_MAX, 4))             # largest finite
    for field in range(1, 255, 13):
        base = int(np.uint32(field) << np.uint32(23))
        out.extend(around(base, 3))
        out.extend(around(base | int(np.uint32(0x007FFFFF)), 3))
    return dedupe(out)


def log_sample(seed, uniform_dense, uniform_wide, subnormal_points):
    """Shared by `log` and `log2`: same domain, same strata, different reference."""
    return [
        ('uniform', uniform_bits(uniform_dense, seed, 0.5, 8.0)),
        ('wide', uniform_bits(uniform_wide, seed ^ 0x9E3779B9, 1e-30, 1e30)),
        ('borders', log_borders()),
        ('subnormal', subnormal_bits(subnormal_points, seed ^ 0x51ED270B)),
        ('specials', special_bits()),
    ]


def log1p_borders():
    """Around zero, around the series/branch boundary, and around -1."""
    out = []
    out.extend(around(0x00000000, 6))          # the values the small guard returns
    out.extend(around(0x80000000, 6))
    edge = int(np.float32(math.sqrt(2.0) - 1.0).view(np.uint32))
    out.extend(around(edge, 8))                # |x| = sqrt(2) - 1: short branch ends
    out.extend(around(edge | 0x80000000, 8))
    # 1 + x losing a bit: x = -1 + 2^-k for every k, where the two-sum earns its
    # place.
    for k in range(0, 30):
        value = np.float32(-1.0 + 2.0 ** -k)
        out.extend(around(gr.float_to_bits(float(value)), 3))
    # Every exponent of a positive argument, and the negatives that still have a
    # real result (|x| < 1).
    for field in range(1, 255, 11):
        base = int(np.uint32(field) << np.uint32(23))
        out.extend(around(base, 3))
    for field in range(1, 127, 7):
        base = int(np.uint32(field) << np.uint32(23)) | 0x80000000
        out.extend(around(base, 3))
    out.extend(around(F32_MAX, 4))
    out.extend(around(F32_MIN_SUB, 4))
    return dedupe(out)


def log1p_sample(seed, uniform_dense, uniform_wide, subnormal_points):
    rng = np.random.default_rng(seed)
    half = uniform_dense // 2
    dense = np.concatenate([
        rng.uniform(-0.999, 1.0, half),
        rng.uniform(1.0, 50.0, uniform_dense - half),
    ]).astype(np.float32).view(np.uint32)
    wide_half = uniform_wide // 2
    wide = np.concatenate([
        -np.exp(rng.uniform(np.log(1e-38), 0.0, wide_half)),
        np.exp(rng.uniform(np.log(1e-38), np.log(1e30), uniform_wide - wide_half)),
    ]).astype(np.float32).view(np.uint32)
    return [
        ('uniform', dense),
        ('wide', wide),
        ('borders', log1p_borders()),
        ('subnormal', subnormal_bits(subnormal_points, seed ^ 0x51ED270B)),
        ('specials', special_bits()),
    ]


def tanh_borders():
    """Both branch boundaries, the saturation edge and the zero neighbourhood."""
    out = []
    out.extend(around(0x00000000, 8))       # the polynomial must keep the sign
    out.extend(around(0x80000000, 8))
    half = int(np.float32(0.5).view(np.uint32))
    out.extend(around(half, 8))             # polynomial / exp2 branch boundary
    out.extend(around(half | 0x80000000, 8))
    saturation = int(np.float32(9.01091385).view(np.uint32))
    out.extend(around(saturation, 8))       # smallest x whose rounded tanh is 1
    out.extend(around(saturation | 0x80000000, 8))
    # Every power of two on both sides, where the polynomial's interval ends and
    # where the exp2 argument crosses an integer.
    for exponent in range(1, 31):
        value = int(np.float32(2.0 ** -exponent).view(np.uint32))
        out.extend(around(value, 2))
        out.extend(around(value | 0x80000000, 2))
    for value in (3.0, 9.0, 10.0, 20.0, 88.0, 1.0e30):
        out.extend(around(int(np.float32(value).view(np.uint32)), 3))
    out.extend(around(F32_MIN_SUB, 4))
    out.extend(around(F32_MAX, 4))
    return dedupe(out)


def tanh_sample(seed, uniform_dense, uniform_wide, subnormal_points):
    rng = np.random.default_rng(seed)
    dense = rng.uniform(-1.5, 1.5, uniform_dense).astype(np.float32)
    signs = rng.choice([-1.0, 1.0], uniform_wide).astype(np.float32)
    magnitudes = np.exp(rng.uniform(np.log(1e-38), np.log(30.0), uniform_wide))
    wide = (signs * magnitudes).astype(np.float32)
    # Past the saturation threshold every input returns +-1, and the buckets above
    # it would otherwise be empty: a hole in the sample is a number too, but an
    # empty bucket in a *saturated* region is a claim nobody checked.
    saturated = (signs[:300] * np.exp(rng.uniform(np.log(9.02), np.log(1e38), 300)))
    return [
        ('uniform', dense.view(np.uint32)),
        ('wide', wide.view(np.uint32)),
        ('saturated', saturated.astype(np.float32).view(np.uint32)),
        ('borders', tanh_borders()),
        ('subnormal', subnormal_bits(subnormal_points, seed ^ 0x51ED270B)),
        ('specials', special_bits()),
    ]


FUNCTIONS = {
    'exp': (ref_exp, exp_sample),
    'exp2': (ref_exp2, exp2_sample),
    'log': (ref_log, log_sample),
    'log1p': (ref_log1p, log1p_sample),
    'log2': (ref_log2, log_sample),
    'rsqrt': (ref_rsqrt, rsqrt_sample),
    'tanh': (ref_tanh, tanh_sample),
}


# --------------------------------------------------------------------------- #
# output
# --------------------------------------------------------------------------- #


def write_csv(path, name, xbits, ref, seed, reference_note):
    lines = [
        '# generated by experiments/m3_fit/gen_golden.py',
        '# function: %s' % name,
        '# reference: %s' % reference_note,
        '# seed: 0x%08X' % seed,
        '# points: %d' % xbits.size,
        '# columns: input_bits_hex,output_bits_hex',
    ]
    body = ['%08x,%08x' % (a, b) for a, b in zip(xbits.tolist(), ref.tolist())]
    with open(path, 'w', encoding='ascii', newline='\n') as handle:
        handle.write('\n'.join(lines) + '\n')
        handle.write('\n'.join(body) + '\n')


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--function', choices=sorted(FUNCTIONS) + ['all'], default='all')
    parser.add_argument('--seed', type=lambda text: int(text, 0), default=DEFAULT_SEED)
    parser.add_argument('--dense-points', type=int, default=3500)
    parser.add_argument('--wide-points', type=int, default=2500)
    parser.add_argument('--subnormal-points', type=int, default=500)
    parser.add_argument('--out-dir', default=os.path.join(REPO, 'data', 'reference'))
    parser.add_argument('--skip-selftest', action='store_true')
    args = parser.parse_args(argv)

    mpmath.mp.dps = MP_DPS
    reference_note = ('mpmath %s at %d decimal digits, direct round-to-nearest-even to float32'
                      % (mpmath.__version__, MP_DPS))

    if not args.skip_selftest:
        print('self-test of the float32 rounding routine')
        gr.selftest()

    os.makedirs(args.out_dir, exist_ok=True)
    names = sorted(FUNCTIONS) if args.function == 'all' else [args.function]
    for name in names:
        func, build = FUNCTIONS[name]
        categories = build(args.seed, args.dense_points, args.wide_points,
                           args.subnormal_points)
        xbits = np.concatenate([block for _, block in categories]).astype(np.uint32)
        ref = np.empty(xbits.size, dtype=np.uint32)
        start = time.perf_counter()
        for i in range(xbits.size):
            ref[i] = np.uint32(reference_one(xbits[i], func))
        elapsed = time.perf_counter() - start

        path = os.path.join(args.out_dir, name + '.csv')
        write_csv(path, name, xbits, ref, args.seed, reference_note)
        print('%-5s %6d points  %.1f s  categories: %s'
              % (name, xbits.size, elapsed,
                 ', '.join('%s=%d' % (label, block.size) for label, block in categories)))
        print('      wrote %s (%d bytes)' % (path, os.path.getsize(path)))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
